"""Commutator closure of a set of strings (x, z), vectorised over the current list."""
import numpy as np

POP = np.array([bin(i).count("1") & 1 for i in range(1 << 16)], dtype=np.uint8)


def par(a):  # parity of the bits of a uint64 array
    a = a ^ (a >> np.uint64(32))
    a = a ^ (a >> np.uint64(16))
    return POP[(a & np.uint64(0xFFFF)).astype(np.int64)]


def closure(gens):
    """All strings in the algebra generated by gens under commutators."""
    G = list(dict.fromkeys(gens))
    seen = set(G)
    xs = np.array([p[0] for p in G], dtype=np.uint64)
    zs = np.array([p[1] for p in G], dtype=np.uint64)
    i = 0
    while i < len(xs):
        x, z = xs[i], zs[i]
        m = par((xs[:i] & z) ^ (zs[:i] & x)).astype(bool)
        new = [p for p in zip((xs[:i][m] ^ x).tolist(), (zs[:i][m] ^ z).tolist()) if p not in seen]
        if new:
            seen.update(new)
            xs = np.concatenate([xs, np.array([a for a, _ in new], dtype=np.uint64)])
            zs = np.concatenate([zs, np.array([b for _, b in new], dtype=np.uint64)])
        i += 1
    return seen
